KNOWN_ENTITIES = {
    "falcon cloud": "organization",
    "acme corp": "organization",
    "widget x": "product",
}

def extract_entities(text, confidence_threshold=0.5):
    # match mentions against known entities
    found = []
    lowered = text.lower()
    for name, entity_type in KNOWN_ENTITIES.items():
        if name in lowered:
            # assign a confidence score
            confidence = 0.9 if len(name) > 8 else 0.4
            if confidence >= confidence_threshold:
                found.append({"name": name, "type": entity_type, "confidence": confidence})
    return found

text = "Falcon Cloud supplies Acme Corp with hosting for Widget X."
entities = extract_entities(text)

print("Extracted entities:")
for e in entities:
    print(f"  {e}")
